import React, { useState } from 'react';
import { Event } from '../types/event';
import { createEvent } from '../services/api';

const EventForm: React.FC = () => {
  const [event, setEvent] = useState<Omit<Event,'id'>>({
    name: '',
    startTime: '',
    endTime: '',
    venue: '',
    attendees: [],
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    if(name==='attendees'){
      setEvent(prev => ({ ...prev, attendees: value.split(',').map(a=>a.trim()) }));
    } else {
      setEvent(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await createEvent({...event, id: crypto.randomUUID()});
    alert('Event created!');
  };

  return (
    <form onSubmit={handleSubmit}>
      <input name='name' placeholder='Event Name' onChange={handleChange} />
      <input type='datetime-local' name='startTime' onChange={handleChange} />
      <input type='datetime-local' name='endTime' onChange={handleChange} />
      <input name='venue' placeholder='Venue' onChange={handleChange} />
      <input name='attendees' placeholder='Attendees (comma-separated)' onChange={handleChange} />
      <button type='submit'>Create Event</button>
    </form>
  );
};

export default EventForm;
